Send SMS.code:
// Send a single SMS.
sendSms({
  // Sender ID approved on your Wigal account.
  senderid: $.configuration.senderId,
  destinations: [{ destination: $.data.phoneNumber }],
  message: 'Your lab results are ready. Please visit the clinic to collect them.',
  smstype: 'text',
});

Send Same Message To Many Recipients.code:
// Alert a list of community health volunteers.
sendSms({
  senderid: $.configuration.senderId,
  // Build one destination per phone number.
  destinations: $.data.volunteers.map(v => ({ destination: v.phone })),
  message: 'Reminder: monthly reporting meeting at the district office on Friday, 9am.',
  smstype: 'text',
});

Send Personalised Messages.code:
// Send personalised payment notifications to beneficiaries.
sendSms({
  senderid: $.configuration.senderId,
  destinations: $.data.payments.map(p => ({
    destination: p.phone,
    // Per-destination message overrides the general one.
    message: `Hello ${p.firstName}, GHS ${p.amount} has been sent to your mobile money wallet.`,
    // Your own reference, useful for matching delivery reports.
    msgid: p.paymentId,
    smstype: 'text',
  })),
});

Send Appointment Reminder.code:
// Remind a patient about their next appointment.
sendSms({
  senderid: $.configuration.senderId,
  destinations: [
    {
      destination: $.data.patientPhone,
      message: `Dear ${$.data.patientName}, your next visit at ${$.data.facility} is on ${$.data.nextVisitDate}.`,
      msgid: $.data.appointmentId,
    },
  ],
  smstype: 'text',
});

Send SMS For Each Record.code:
// Send one SMS per registered household.
each(
  $.data.households,
  // Inside each(), $.data is the current household.
  sendSms({
    senderid: $.configuration.senderId,
    destinations: [{ destination: $.data.headPhone }],
    message: 'Your household has been enrolled in the programme. Keep this message for reference.',
    smstype: 'text',
  })
);
